int main() {
    // 处理输入
    string s;
    cin>>s;
    vector<string> colRow = split(s, ",");
    int col,row;
    row = stoi(colRow[0]);
    col = stoi(colRow[1]);
​
    vector<vector<string>> ans(row);
    for (int i = 0; i < row; i++) {
        string tmp;
        cin >> tmp;
        ans[i] =  split(tmp, ",");
    }

    int direct[4][2] = {{0,1}, {1,0},{1,1}, {1,-1}};

    int res = 0;
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++) {
            if ("M" == ans[i][j]) {
                for (int k = 0; k < 4; k++) {
                    int offsetX = direct[k][0];
                    int offsetY = direct[k][1];
                    int lastX = i - offsetX;
                    int lastY = j - offsetY;
                    // 与上一个处于同一直线，已经计算过了，减少重复运算
                    if (lastX >= 0 && lastX  < row && lastY >= 0 && lastY < col && ans[lastX][lastY] == "M") {
                        continue;
                    }
​
                    int count = 1;
                    int nextX = i + offsetX;
                    int nextY = j + offsetY;
                    while (nextX >= 0 && nextX  < row && nextY >= 0 && nextY < col && ans[nextX][nextY] == "M" ) {
                        count++;
                        nextX += offsetX;
                        nextY += offsetY;
                    }
                    res = max(res, count);
                }
            }
        }
    }
    cout << res;
    return 0;
}

