    input = strings.TrimSpace(input)
    colRow := strings.Split(input, ",")
    row, _ := strconv.Atoi(colRow[0])
    col, _ := strconv.Atoi(colRow[1])
​
    ans := make([][]string, row)
    for i := 0; i < row; i++ {
        line, _ := reader.ReadString('\n')
        line = strings.TrimSpace(line)
        ans[i] = strings.Split(line, ",")
    }
​
    direct := [4][2]int{{0, 1}, {1, 0}, {1, 1}, {1, -1}}
    res := 0
​
    for i := 0; i < row; i++ {
        for j := 0; j < col; j++ {
            if ans[i][j] == "M" {
                for _, d := range direct {
                    offsetX, offsetY := d[0], d[1]
                    lastX, lastY := i-offsetX, j-offsetY
​
                    // 与上一个处于同一直线，已经计算过了，减少重复运算
                    if lastX >= 0 && lastX < row && lastY >= 0 && lastY < col && ans[lastX][lastY] == "M" {
                        continue
                    }
​
                    count := 1
                    nextX, nextY := i+offsetX, j+offsetY
                    for nextX >= 0 && nextX < row && nextY >= 0 && nextY < col && ans[nextX][nextY] == "M" {
                        count++
                        nextX += offsetX
                        nextY += offsetY
                    }
                    res = max(res, count)
                }
            }
        }
    }
​
